def min_remaining_space(V, n, volumes):
    # Initialize a two-dimensional array to store the maximum occupied volume for each subset of items
    dp = [[0] * (n + 1) for _ in range(n + 1)]

    # Loop through each item and its corresponding volume
    for i in range(1, n + 1):
        for j in range(1, n + 1):
            # If the current item's volume is greater than the box's capacity, there is no space left
            if volumes[i - 1] > V:
                dp[i][j] = 0
            # If the current item is the last item, its volume is the maximum occupied volume
            elif i == j:
                dp[i][j] = volumes[i - 1]
            # Otherwise, calculate the maximum occupied volume for the current subset of items
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i - 1][j - 1] + volumes[i - 1])

    # Return the difference between the box's total capacity and the maximum occupied volume
    return V - dp[n][n]

def total_smoked_cigarettes(n, k):
    total = 0
    while n >= k:
        total += n // k
        n = n // k + (n % k)
    return total + n
